package com.spai.portal.task.domain;
import java.time.OffsetDateTime;import javax.persistence.*;
@Entity @Table(name="task_progress",uniqueConstraints=@UniqueConstraint(columnNames={"task_id","team_id"})) public class TaskProgress {@Id private String id;@Column(name="task_id",nullable=false)private String taskId;@Column(name="team_id",nullable=false)private String teamId;@Column(nullable=false)private String status="待创建";@Version @Column(name="lock_version",nullable=false)private long lockVersion;@Column(name="updated_by")private String updatedBy;@Column(name="updated_at",nullable=false)private OffsetDateTime updatedAt=OffsetDateTime.now();public String getId(){return id;}public void setId(String id){this.id=id;}public String getTaskId(){return taskId;}public void setTaskId(String taskId){this.taskId=taskId;}public String getTeamId(){return teamId;}public void setTeamId(String teamId){this.teamId=teamId;}public String getStatus(){return status;}public void setStatus(String status){this.status=status;}public long getLockVersion(){return lockVersion;}public void setLockVersion(long lockVersion){this.lockVersion=lockVersion;}public String getUpdatedBy(){return updatedBy;}public void setUpdatedBy(String updatedBy){this.updatedBy=updatedBy;}public OffsetDateTime getUpdatedAt(){return updatedAt;}public void setUpdatedAt(OffsetDateTime updatedAt){this.updatedAt=updatedAt;}}
